do $$ begin
if (select data#>>'{image}' from public.cms_sections where page_id='fleet-visibility--fleet-equipment' and key='sectionOne') is distinct from '/fleet-and-visiblity/fleet-and-equipment/section-1-main-image.png' then raise exception 'Wrong image: fleet-visibility--fleet-equipment {image}'; end if;
if (select data#>>'{services,0,image}' from public.cms_sections where page_id='fleet-visibility--fleet-equipment' and key='sectionThree') is distinct from '/fleet-and-visiblity/fleet-and-equipment/section-3-image-1.png' then raise exception 'Wrong image: fleet-visibility--fleet-equipment {services,0,image}'; end if;
if (select data#>>'{services,1,image}' from public.cms_sections where page_id='fleet-visibility--fleet-equipment' and key='sectionThree') is distinct from '/fleet-and-visiblity/fleet-and-equipment/section-3-image-2.png' then raise exception 'Wrong image: fleet-visibility--fleet-equipment {services,1,image}'; end if;
if (select data#>>'{services,2,image}' from public.cms_sections where page_id='fleet-visibility--fleet-equipment' and key='sectionThree') is distinct from '/fleet-and-visiblity/fleet-and-equipment/section-3-image-3.png' then raise exception 'Wrong image: fleet-visibility--fleet-equipment {services,2,image}'; end if;
if (select data#>>'{services,3,image}' from public.cms_sections where page_id='fleet-visibility--fleet-equipment' and key='sectionThree') is distinct from '/fleet-and-visiblity/fleet-and-equipment/section-3-image-4.png' then raise exception 'Wrong image: fleet-visibility--fleet-equipment {services,3,image}'; end if;
if (select data#>>'{services,4,image}' from public.cms_sections where page_id='fleet-visibility--fleet-equipment' and key='sectionThree') is distinct from '/fleet-and-visiblity/fleet-and-equipment/section-3-image-5.png' then raise exception 'Wrong image: fleet-visibility--fleet-equipment {services,4,image}'; end if;
if (select data#>>'{image}' from public.cms_sections where page_id='fleet-visibility--nationwide-network' and key='sectionOne') is distinct from '/fleet-and-visiblity/nationwide-network/section-1-main-image.png' then raise exception 'Wrong image: fleet-visibility--nationwide-network {image}'; end if;
if (select data#>>'{locations,0,image}' from public.cms_sections where page_id='fleet-visibility--nationwide-network' and key='sectionFour') is distinct from '/fleet-and-visiblity/nationwide-network/section-4-image-1.png' then raise exception 'Wrong image: fleet-visibility--nationwide-network {locations,0,image}'; end if;
if (select data#>>'{locations,1,image}' from public.cms_sections where page_id='fleet-visibility--nationwide-network' and key='sectionFour') is distinct from '/fleet-and-visiblity/nationwide-network/section-4-image-2.png' then raise exception 'Wrong image: fleet-visibility--nationwide-network {locations,1,image}'; end if;
if (select data#>>'{locations,2,image}' from public.cms_sections where page_id='fleet-visibility--nationwide-network' and key='sectionFour') is distinct from '/fleet-and-visiblity/nationwide-network/section-4-image-3.png' then raise exception 'Wrong image: fleet-visibility--nationwide-network {locations,2,image}'; end if;
if (select data#>>'{locations,3,image}' from public.cms_sections where page_id='fleet-visibility--nationwide-network' and key='sectionFour') is distinct from '/fleet-and-visiblity/nationwide-network/section-4-image-4.png' then raise exception 'Wrong image: fleet-visibility--nationwide-network {locations,3,image}'; end if;
if (select data#>>'{locations,4,image}' from public.cms_sections where page_id='fleet-visibility--nationwide-network' and key='sectionFour') is distinct from '/fleet-and-visiblity/nationwide-network/section-4-image-5.png' then raise exception 'Wrong image: fleet-visibility--nationwide-network {locations,4,image}'; end if;
if (select data#>>'{image}' from public.cms_sections where page_id='fleet-visibility--shipment-tracking-operational-visibility' and key='sectionOne') is distinct from '/fleet-and-visiblity/shipment-tracking-and-visibility/section-1-main-image.png' then raise exception 'Wrong image: fleet-visibility--shipment-tracking-operational-visibility {image}'; end if;
if (select data#>>'{image}' from public.cms_sections where page_id='fleet-visibility--shipment-tracking-operational-visibility' and key='sectionThree') is distinct from '/fleet-and-visiblity/shipment-tracking-and-visibility/section-3-main-image.png' then raise exception 'Wrong image: fleet-visibility--shipment-tracking-operational-visibility {image}'; end if;
if (select data#>'{services,5}' from public.cms_sections where page_id='fleet-visibility--fleet-equipment' and key='sectionThree')<>'{}'::jsonb then raise exception 'Cleared client recreated'; end if;
if exists(select 1 from public.cms_sections where page_id='fleet-visibility--nationwide-network' and key='sectionOne' and (enabled or data->>'heading'<>'Edited heading' or revision<>71)) then raise exception 'Text/visibility/revision changed'; end if;
if (select count(*) from public.cms_history where actor='System: Fleet page images added')<>6 then raise exception 'Wrong audit count or repeated migration'; end if;
perform public.cms_validate(template,data,'','') from public.cms_sections where page_id='fleet-visibility--shipment-tracking-operational-visibility' and key='sectionThree';
end $$;
